/*
 * A209765  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A209766; see the Formula section.
 * https://oeis.org/A209765
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   A209765 computed by flattening coefficients of the polynomials
 *            u(n,x) generated by u(n,x)=x*u(n-1,x)+(x+1)*v(n-1,x),
 *            v(n,x)=2x*u(n-1,x)+x*v(n-1,x)+1, with u(1,x)=1 and v(1,x)=1
 * Range:     u8 n <= 25, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <math.h>

static seq_t **rows = NULL;          /* pointers to all computed rows of u */
static idx_t   num_rows = 0;         /* number of rows already computed */

/* previous row polynomials (u and v) */
static seq_t *u_prev = NULL;
static seq_t *v_prev = NULL;

/* smallest r with r*(r+1)/2 >= n */
static idx_t
row_of(idx_t n)
{
    /* use long double for better precision */
    long double d = sqrt((long double)(8.0L * n + 1.0L));
    idx_t r = (idx_t)((d - 1.0L) / 2.0L);
    while (r * (r + 1) / 2 < n) ++r;
    return r;
}

/* generate rows up to r inclusive */
static void
ensure_rows(idx_t r)
{
    if (num_rows >= r) return;

    /* grow rows array if necessary */
    if (!rows) {
        rows = (seq_t**)malloc(r * sizeof(seq_t*));
    } else if (num_rows < r) {
        rows = (seq_t**)realloc(rows, r * sizeof(seq_t*));
    }

    for (idx_t cur = num_rows + 1; cur <= r; ++cur) {
        idx_t len = cur;                       /* current row length = cur */
        seq_t *u_new = (seq_t*)malloc(len * sizeof(seq_t));
        seq_t *v_new = (seq_t*)calloc(len, sizeof(seq_t)); /* init to 0 */

        if (cur == 1) {            /* base row */
            u_new[0] = 1;
            v_new[0] = 1;
        } else {
            /* v_new[0] is always 1 */
            v_new[0] = 1;
            for (idx_t k = 1; k < len; ++k) {
                /* v_new[k] = 2*u_prev[k-1] + v_prev[k-1] */
                v_new[k] = 2 * u_prev[k-1] + v_prev[k-1];
            }

            /* u_new[k] = (k>0 ? u_prev[k-1]+v_prev[k-1] : 0)
                         + (k < len-1 ? v_prev[k] : 0) */
            for (idx_t k = 0; k < len; ++k) {
                seq_t a = (k > 0) ? u_prev[k-1] + v_prev[k-1] : 0;
                seq_t b = (k < len-1) ? v_prev[k] : 0;
                u_new[k] = a + b;
            }
        }

        rows[cur-1] = u_new;   /* store the new row */

        /* free the previous v_prev array (not needed further) */
        if (v_prev) free(v_prev);

        u_prev = u_new;
        v_prev = v_new;
    }
    num_rows = r;
}

seq_t a(idx_t n)
{
    if (n < 1) return 0;          /* not used, but safeguard */

    idx_t r = row_of(n);          /* row number (1‑based) */
    ensure_rows(r);

    idx_t tri_prev = (r - 1) * r / 2;   /* T(r-1) */
    idx_t col = n - tri_prev - 1;       /* column in the row, 0‑based */

    return rows[r-1][col];
}
